import { mkdirSync, writeFileSync, readFileSync, existsSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url))
const PKG_ROOT = resolve(SCRIPT_DIR, '..')
const OUTPUT_PATH = resolve(PKG_ROOT, 'src', 'styles', 'tokens.generated.css')
const THEME_OUTPUT_PATH = resolve(PKG_ROOT, 'src', 'styles', 'theme.generated.css')

type Core = typeof import('@canshift/core')

const HEADER = [
  '/* AUTO-GENERATED by scripts/generate-tokens.css.ts — DO NOT EDIT BY HAND */',
  '/* Source of truth: @canshift/core (DARK_TOKENS + BRAND_TOKENS + FONT_TOKENS) */',
  '',
].join('\n')

const buildBlock = (opening: string, cssVars: Record<string, string>): string => {
  const lines = [`${opening} {`]
  for (const [name, value] of Object.entries(cssVars)) {
    lines.push(`  ${name}: ${value};`)
  }
  lines.push('}', '')
  return `${HEADER}\n${lines.join('\n')}`
}

const hslColorVars = (cssVars: readonly string[]): Record<string, string> =>
  Object.fromEntries(
    cssVars.map((cssVar) => [`--color-${cssVar.replace(/^--/, '')}`, `hsl(var(${cssVar}))`])
  )

const themeVars = (core: Core): Record<string, string> => ({
  '--font-sans': `var(${core.FONT_UI_CSS_VAR})`,
  '--font-mono': `var(${core.FONT_MONO_CSS_VAR})`,
  ...hslColorVars(Object.values(core.COLOR_KEY_TO_CSS_VAR)),
  ...hslColorVars(Object.values(core.BRAND_COLOR_KEY_TO_CSS_VAR)),
  ...hslColorVars(core.BRAND_NEUTRAL_STEPS.map(core.brandNeutralCssVar)),
  ...hslColorVars([core.BRAND_TEXT_CSS_VAR]),
  [`--color-${core.BRAND_DIVIDER_CSS_VAR.replace(/^--/, '')}`]: `var(${core.BRAND_DIVIDER_CSS_VAR})`,
})

const rootVars = (core: Core): Record<string, string> => ({
  ...core.tokensToCssVars(core.DARK_TOKENS),
  ...core.brandTokensToCssVars(core.BRAND_TOKENS),
  ...core.fontTokensToCssVars(core.FONT_TOKENS),
})

const writeIfChanged = (path: string, content: string): void => {
  const rel = path.replace(`${PKG_ROOT}/`, '')
  if (existsSync(path) && readFileSync(path, 'utf8') === content) {
    console.log(`[tokens:gen] up to date — ${rel}`)
    return
  }
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, content, 'utf8')
  console.log(`[tokens:gen] wrote ${rel}`)
}

const main = async () => {
  const core = await import('@canshift/core')
  writeIfChanged(OUTPUT_PATH, buildBlock(':root', rootVars(core)))
  writeIfChanged(THEME_OUTPUT_PATH, buildBlock('@theme inline reference', themeVars(core)))
}

try {
  await main()
} catch (err) {
  const message = err instanceof Error ? err.message : String(err)
  console.error(`[tokens:gen] error: ${message}`)
  process.exit(1)
}
